-- Delivery jobs: generated by the module, taken at the origin, handed off at the destination
-- only. One ship.

T.suite("jobs")

local HOME = "Port Vesper"
local m, c0

T.step("post a delivery", function()
    m = T.postJob(T.makeJob("delivery", HOME))
    T.eq("generated: type", m.type, "delivery")
    T.eq("generated: origin", m.origin, HOME)
    T.check("generated: a destination that is not the origin", m.dest and m.dest ~= HOME, m.dest)
    T.check("generated: reward is a multiple of 5", m.reward > 0 and m.reward % 5 == 0, m.reward)
    T.check("generated: summary names cargo and destination", m.short:find(m.cargo, 1, true) ~= nil, m.short)
end)
T.takeJob(function() return m end)
T.step("taken", function()
    T.check("delivery: active", T.activeEntry(m) ~= nil)
    T.check("delivery: time limit set from distance", m._time_limit and m._time_limit >= 180, m._time_limit)
end)
T.talk(HOME, {})
T.step("not at the origin", function() T.check("delivery: no hand-off at the origin", not T.hasReply("Hand off")) end)
T.dock(function() return T.find(m.dest) end)
T.wait(1.5)   -- arriving in a new region pays survey credits; let that land first
T.step("note credits", function() c0 = T.credits() end)
T.talk(function() return T.find(m.dest) end, {"Hand off"})
T.step("delivered", function()
    T.eq("delivery: paid the reward", T.credits() - c0, m.reward)
    T.check("delivery: done", T.activeEntry(m) == nil)
end)
T.talk(function() return T.find(m.dest) end, {})
T.step("only once", function() T.check("delivery: no second hand-off", not T.hasReply("Hand off")) end)
T.closeComms()
